export function vehiclePowertrainControls(key,rows,attrs,esc,{disabled=false}={}){const torque=key==='torqueCurve',off=disabled?' disabled':'';return '<div class="vehicle-powertrain-rows"><table><thead><tr><th>'+(torque?'RPM':'기어')+'</th><th>'+(torque?'토크 배율':'기어비')+'</th><th></th></tr></thead><tbody>'+rows.map((row,i)=>{const input=field=>'<input type="number" step="any" '+attrs+' data-vehicle-row-index="'+i+'" data-vehicle-row-field="'+field+'" aria-label="'+(torque?'토크 키 ':'기어 ')+(i+1)+' '+field+'" value="'+esc(torque?row[field]:row)+'"'+off+'>';return '<tr><td>'+(torque?input('rpm'):i+1)+'</td><td>'+input(torque?'torque':'ratio')+'</td><td><button '+attrs+' data-vehicle-row-remove="'+i+'" aria-label="행 '+(i+1)+' 삭제"'+off+'>삭제</button></td></tr>';}).join('')+'</tbody></table><button '+attrs+' data-vehicle-row-add="'+key+'"'+off+'>추가</button></div>';}
export function editVehiclePowertrainRows(rows,key,input){const next=structuredClone(rows);if(input.dataset.vehicleRowAdd!==undefined){if(key==='torqueCurve')next.push({rpm:(next.at(-1)?.rpm||0)+500,torque:next.at(-1)?.torque??1});else next.push(next.at(-1)||1);}else if(input.dataset.vehicleRowRemove!==undefined)next.splice(Number(input.dataset.vehicleRowRemove),1);else{const index=Number(input.dataset.vehicleRowIndex);if(!Number.isInteger(index)||index<0||index>=next.length)throw Error('차량 설정 행을 확인하세요.');if(key==='torqueCurve'){const field=input.dataset.vehicleRowField;if(!['rpm','torque'].includes(field))throw Error('토크 키를 확인하세요.');next[index][field]=Number(input.value);}else next[index]=Number(input.value);}return next;}
